B.acJ=s([u.m,"Sazona los filetes y d\xf3ralos a fuego fuerte 2 minutos por lado.","Baja el fuego, a\xf1ade la salsa y deja 3-4 minutos.","S\xedrvelo con las patatas."],t.s)
B.aKD=new A.aU("lomo-champinon","Lomo en salsa de champi\xf1\xf3n con patatas al horno",35,"1 raci\xf3n",B.ae0,B.acJ,"Se puede hacer por lotes el jueves y guardar 3 d\xedas en la nevera.",560,39,B.U,B.d3,!1)
